// rehash.go v2 — backfill repair for PR #520, literal-free edition.
// All scrub patterns are composed at runtime from fragments so that no
// tool input (including this file's own content) ever contains the
// identifiers being scrubbed — otherwise each fix-commit's audit seal
// re-leaks them. Adds macOS slug variant and a --scan mode.
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

const previewLimit = 200

// runtime-composed identifier fragments — never a whole literal
var name = "jfre" + "eman"
var tokenHome = "[RED" + "ACTED:home-path]"

var pairs = [][2]string{
	{"-home-" + name + "-", "-home-user-"},
	{"-Users-" + name + "-", "-Users-user-"},
	{"/home/" + name + "/", tokenHome},
	{"/Users/" + name + "/", tokenHome},
	{"/home/" + name, tokenHome},
	{"/Users/" + name, tokenHome},
}

var scanPatterns = []string{
	"-home-" + name, "-Users-" + name, "/home/" + name, "/Users/" + name,
}

func scrubText(s string) string {
	for _, p := range pairs {
		s = strings.ReplaceAll(s, p[0], p[1])
	}
	return s
}

func needsScrub(s string) bool {
	for _, p := range scanPatterns {
		if strings.Contains(s, p) {
			return true
		}
	}
	return false
}

func scrubValue(v any) (any, bool) {
	switch t := v.(type) {
	case string:
		n := scrubText(t)
		return n, n != t
	case map[string]any:
		ch := false
		for k, val := range t {
			nv, c := scrubValue(val)
			t[k] = nv
			ch = ch || c
		}
		return t, ch
	case []any:
		ch := false
		for i, val := range t {
			nv, c := scrubValue(val)
			t[i] = nv
			ch = ch || c
		}
		return t, ch
	default:
		return v, false
	}
}

func processLine(line string) (string, bool, error) {
	if !needsScrub(line) {
		return line, false, nil
	}
	dec := json.NewDecoder(strings.NewReader(line))
	dec.UseNumber()
	var obj map[string]any
	if err := dec.Decode(&obj); err != nil {
		return line, false, fmt.Errorf("parse: %w", err)
	}
	oldHash, _ := obj["tool_input_hash"].(string)
	oldPrev, hadPrev := obj["tool_input_preview"].(string)
	_, hasTI := obj["tool_input"]
	if !hasTI {
		out := scrubText(line)
		return out, out != line, nil
	}
	ti, _ := scrubValue(obj["tool_input"])
	data, err := json.Marshal(ti)
	if err != nil {
		return line, false, err
	}
	sum := sha256.Sum256(data)
	newHash := hex.EncodeToString(sum[:])
	s := string(data)
	newPrev := s
	if len(s) > previewLimit {
		newPrev = s[:previewLimit] + "..."
	}
	out := scrubText(line)
	if oldHash != "" && oldHash != newHash {
		if strings.Count(out, oldHash) != 1 {
			return line, false, fmt.Errorf("hash count %d", strings.Count(out, oldHash))
		}
		out = strings.Replace(out, oldHash, newHash, 1)
	}
	if hadPrev {
		newPrevRaw, _ := json.Marshal(newPrev)
		key := `"tool_input_preview":`
		i := strings.Index(out, key+`"`)
		if i < 0 {
			return line, false, fmt.Errorf("preview key missing")
		}
		j := i + len(key)
		k := j + 1
		for k < len(out) {
			if out[k] == '\\' {
				k += 2
				continue
			}
			if out[k] == '"' {
				break
			}
			k++
		}
		out = out[:j] + string(newPrevRaw) + out[k+1:]
		_ = oldPrev
	}
	if !strings.Contains(out, `"redacted":true`) {
		if !strings.HasSuffix(out, "}") {
			return line, false, fmt.Errorf("no closing brace")
		}
		out = out[:len(out)-1] + `,"redacted":true}`
	}
	vdec := json.NewDecoder(strings.NewReader(out))
	vdec.UseNumber()
	var vo map[string]any
	if err := vdec.Decode(&vo); err != nil {
		return line, false, fmt.Errorf("verify parse: %w", err)
	}
	vdata, err := json.Marshal(vo["tool_input"])
	if err != nil {
		return line, false, err
	}
	vsum := sha256.Sum256(vdata)
	if got, _ := vo["tool_input_hash"].(string); got != hex.EncodeToString(vsum[:]) {
		return line, false, fmt.Errorf("verify hash mismatch")
	}
	if needsScrub(out) {
		return line, false, fmt.Errorf("remnant survives scrub")
	}
	return out, out != line, nil
}

func main() {
	mode := ""
	raw := false
	for _, arg := range os.Args[1:] {
		switch arg {
		case "--scan":
			mode = "scan"
			continue
		case "--raw":
			raw = true
			continue
		}
		b, err := os.ReadFile(arg)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		lines := strings.Split(strings.TrimRight(string(b), "\n"), "\n")
		n := 0
		if mode == "scan" {
			for _, line := range lines {
				if needsScrub(line) {
					n++
				}
			}
			if n > 0 {
				fmt.Printf("REMNANTS %d %s\n", n, arg)
			}
			continue
		}
		for i, line := range lines {
			if line == "" {
				continue
			}
			if raw {
				nl := scrubText(line)
				if nl != line {
					lines[i], n = nl, n+1
				}
				continue
			}
			nl, ch, err := processLine(line)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s:%d: %v\n", arg, i+1, err)
				os.Exit(1)
			}
			if ch {
				lines[i], n = nl, n+1
			}
		}
		if n > 0 {
			if err := os.WriteFile(arg, []byte(strings.Join(lines, "\n")+"\n"), 0o644); err != nil {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(1)
			}
		}
		fmt.Printf("%s: %d updated (raw=%v)\n", arg, n, raw)
		raw = false
	}
	if mode == "scan" {
		fmt.Println("scan done")
	}
}
